function renderControls(){for(const k of ['bpm','swing','tone','space','master'])$('#'+k).value=state[k];$('#swing-value').textContent=state.swing+'%';$('#tone-value').textContent=state.tone>=1000?(state.tone/1000).toFixed(1)+' kHz':state.tone+' Hz';$('#space-value').textContent=state.space+'%';$('#master-value').textContent=state.master+'%';$('#trim-start').value=state.trimStart;$('#trim-end').value=state.trimEnd;$('#reverse').setAttribute('aria-pressed',state.reverse);$('#sample-name').textContent=state.sampleName;$('#project-title').textContent=state.title;$('#project-meta').textContent=state.keyLabel.toUpperCase()+' · '+state.steps/4+' BEATS · '+(state.preset>=3?'RADIOHEAD STUDY':'ORIGINAL SKETCH');$('.key strong').textContent=state.keyLabel;$('#loop-length').textContent=state.steps/4+' BEATS';$('#pattern-summary').textContent=state.steps+' steps · '+(state.steps/((state.beatsPerBar||4)*4))+' bars / 1⁄16';$('.session-number').textContent=state.preset>=3?'0'+(state.preset-2):'REC';$$('input[type=range]').forEach(setRange);$('#xy-dot').style.left=(state.tone-150)/8350*100+'%';$('#xy-dot').style.top=(1-state.space/70)*100+'%';$('#xy-pad').setAttribute('aria-valuenow',state.tone);renderMachine();}
function render(){renderPresets();renderBanks();renderEditor();renderMixer();renderControls();renderStudy();renderLesson();drawWave();}
function referenceMaterial(){
 if(state.preset<0)return null;const key=state.preset+':'+state.steps+':'+track;
 if(!referenceCache.has(key)){const original=makeState(state.preset),repeat=row=>Array.from({length:state.steps},(_,i)=>row[i%row.length]);referenceCache.set(key,{pattern:original.patterns[track].map(repeat),holds:Array.from({length:8},(_,r)=>repeat(original.holds?.[r]||Array(original.steps).fill(0)))});}
 return referenceCache.get(key);
}
function clearWrittenTrack(){state.patterns[track].forEach(row=>row.fill(0));if(track==='keys')state.holds?.forEach(row=>row.fill(0));}
function updateRebuildScore(){const el=$('#rebuild-score');if(state.preset<0){el.textContent='';return;}const original=referenceMaterial().pattern;let target=0,placed=0,correct=0;state.patterns[track].forEach((row,r)=>row.forEach((value,i)=>{if(original[r][i])target++;if(value){placed++;if(original[r][i])correct++;}}));el.textContent=showReference||placed!==target?track.toUpperCase()+' REBUILD / '+(target+placed?Math.round(2*correct/(target+placed)*100):100)+'% MATCH · '+correct+' / '+target+' REFERENCE HITS':'';}
function editCell(cell,value){setFollow(false);const r=+cell.dataset.row,s=+cell.dataset.step;state.patterns[track][r][s]=value;if(track==='keys'&&state.holds)state.holds[r][s]=value&&showReference?referenceMaterial()?.holds[r][s]||0:0;cell.classList.toggle('on',!!value);cell.classList.toggle('reference',showReference&&!value&&state.preset>=0&&!!referenceMaterial().pattern[r][s]);cell.style.setProperty('--velocity',value*65+'%');cell.setAttribute('aria-pressed',!!value);updateRebuildScore();renderCouchCue();}
let gesture=null;
$('#editor').addEventListener('pointerdown',async e=>{const cell=e.target.closest('button.step-cell');if(!cell)return;e.preventDefault();remember();const value=state.patterns[track][+cell.dataset.row][+cell.dataset.step]?0:e.pointerType==='pen'&&e.pressure>0?Math.max(.15,e.pressure):.78;gesture={value,last:cell,pointer:e.pointerId};editCell(cell,value);$('#input-status').textContent=e.pointerType==='pen'?'PENCIL / PRESSURE VELOCITY':'TOUCH + MOUSE READY';$('#editor').setPointerCapture(e.pointerId);try{await ensureAudio();if(!playing&&value)engine.hit(track,+cell.dataset.row,ctx.currentTime,value);}catch(err){toast(err.message);}});
