function xy(e){const r=$('#xy-pad').getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));state.tone=Math.round(150+x*8350);state.space=Math.round((1-y)*70);renderControls();updateAudio();}
$('#xy-pad').addEventListener('pointerdown',e=>{remember();$('#xy-pad').setPointerCapture(e.pointerId);xy(e);});$('#xy-pad').addEventListener('pointermove',e=>{if($('#xy-pad').hasPointerCapture(e.pointerId))xy(e);});$('#xy-pad').addEventListener('pointerup',autosave);$('#xy-pad').addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();remember();state.tone=Math.max(150,Math.min(8500,state.tone+(e.key==='ArrowRight'?200:e.key==='ArrowLeft'?-200:0)));state.space=Math.max(0,Math.min(70,state.space+(e.key==='ArrowUp'?3:e.key==='ArrowDown'?-3:0)));renderControls();updateAudio();autosave();});
for(let i=0;i<4;i++){const b=document.createElement('button');b.textContent='0'+(i+1);b.setAttribute('aria-label','Play sample slice '+(i+1));b.onclick=()=>auditionSlice(i);$('#sample-pads').append(b);}
async function auditionSlice(i){try{await ensureAudio();engine.slice(i,ctx.currentTime,.9);const b=$$('#sample-pads button')[i];b.classList.add('hit');setTimeout(()=>b.classList.remove('hit'),180);}catch(e){toast(e.message);}}
function drawWave(){const canvas=$('#waveform');if(!canvas)return;const rect=canvas.getBoundingClientRect();if(!rect.width)return;const dpr=window.devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);const w=rect.width,h=rect.height-20;c.clearRect(0,0,w,rect.height);const data=engine?.sample?.getChannelData(0);for(let x=0;x<w;x+=2){let amplitude=0;if(data){const start=Math.floor(x/w*data.length),end=Math.floor((x+2)/w*data.length),stride=Math.max(1,Math.floor((end-start)/20));for(let j=start;j<end;j+=stride)amplitude=Math.max(amplitude,Math.abs(data[j]||0));}else{const t=x/w*2.4,local=t%.6;amplitude=Math.abs(Math.sin(x*1.83))*Math.exp(-local*9)*.8;}c.strokeStyle=x/w<state.trimStart/100||x/w>state.trimEnd/100?'#3d4934':'#a3ba7d';c.beginPath();c.moveTo(x,h/2-amplitude*h*.43);c.lineTo(x,h/2+amplitude*h*.43+1);c.stroke();}const start=state.trimStart/100*w,end=state.trimEnd/100*w;c.fillStyle='#d3e5a408';c.fillRect(start,0,end-start,h);for(let i=0;i<=4;i++){const x=start+(end-start)*i/4;c.strokeStyle=i===0||i===4?'#bdcf96':'#6d8056';c.setLineDash(i===0||i===4?[]:[3,4]);c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke();}$('#sample-duration').textContent=engine?engine.sample.duration.toFixed(2)+' SEC · 4 SLICES':'4 SLICES · READY TO PLAY';}
new ResizeObserver(drawWave).observe($('#waveform'));
for(const name of ['trim-start','trim-end']){$('#'+name).addEventListener('pointerdown',remember);$('#'+name).oninput=()=>{if(name==='trim-start')state.trimStart=Math.min(+$('#trim-start').value,state.trimEnd-1);else state.trimEnd=Math.max(+$('#trim-end').value,state.trimStart+1);renderControls();drawWave();autosave();};}
