$('#load-reference').onclick=()=>$('#reference-file').click();
$('#reference-file').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.size>120*1024*1024){toast('Choose a reference recording under 120 MB.');return;}if(referenceURL)URL.revokeObjectURL(referenceURL);referenceURL=URL.createObjectURL(file);$('#reference-audio').src=referenceURL;$('#reference-title').textContent=file.name;$('#reference-a').value=0;$('#reference-b').value=0;toast('Reference loaded locally. Set A and B to practice a passage.');e.target.value='';};
function normalizeReference(changed='a'){
 const audio=$('#reference-audio'),duration=audio.duration;if(!Number.isFinite(duration)||duration<=0)return;
 const gap=Math.min(.05,duration/2);let a=Math.max(0,Math.min(duration-gap,Number($('#reference-a').value)||0)),b=Math.max(gap,Math.min(duration,Number($('#reference-b').value)||duration));
 if(b<a+gap){if(changed==='b')a=Math.max(0,b-gap);else b=Math.min(duration,a+gap);}
 $('#reference-a').value=a.toFixed(3);$('#reference-b').value=b.toFixed(3);
}
function setReferenceSpeed(){const audio=$('#reference-audio');audio.playbackRate=+$('#reference-speed').value;audio.preservesPitch=true;if('webkitPreservesPitch' in audio)audio.webkitPreservesPitch=true;}
function checkReferenceLoop(){const audio=$('#reference-audio');if(audio.paused||audio.seeking||!$('#reference-loop').checked)return;const a=+$('#reference-a').value,b=+$('#reference-b').value;if(b>a&&(audio.currentTime>=b||audio.currentTime<a-.025))audio.currentTime=a;}
$('#reference-audio').onloadedmetadata=()=>{const duration=$('#reference-audio').duration;if(!Number.isFinite(duration)||duration<=0)return;$('#reference-b').value=duration.toFixed(3);$('#reference-a').max=duration;$('#reference-b').max=duration;normalizeReference();setReferenceSpeed();};
$('#reference-audio').onerror=()=>{if(referenceURL)toast('This recording could not be decoded. Try MP3, AAC or WAV.');};
for(const id of ['reference-a','reference-b'])$('#'+id).onchange=()=>normalizeReference(id==='reference-a'?'a':'b');
$('#reference-audio').onplay=()=>{if(playing||starting)stop(false);normalizeReference();checkReferenceLoop();};
$('#reference-audio').ontimeupdate=checkReferenceLoop;
$('#reference-audio').onended=()=>{if($('#reference-loop').checked){$('#reference-audio').currentTime=+$('#reference-a').value;$('#reference-audio').play().catch(()=>{});}};
$('#set-reference-a').onclick=()=>{$('#reference-a').value=$('#reference-audio').currentTime;normalizeReference('a');};
$('#set-reference-b').onclick=()=>{$('#reference-b').value=$('#reference-audio').currentTime;normalizeReference('b');};
