function syncMachineTransport(){const button=$('#machine-play');button.classList.toggle('is-playing',playing||starting);button.setAttribute('aria-label',playing||starting?'Pause loop':'Play loop');button.querySelector('.play-caption').textContent=starting?'STARTING…':playing?'PAUSE':'PLAY LOOP';button.disabled=!machinePowered;$('#menu-transport').disabled=!machinePowered;$('#menu-transport').textContent=starting?'Cancel':playing?'Pause':'Play';$('#menu-transport').setAttribute('aria-label',playing||starting?'Pause loop':'Play loop');$('#desktop-status').textContent=starting?'Preparing audio…':playing?'Playing · change a layer, or play the pads.':'Ready. Start a loop, or play the four pads.';}
