const machineCanvas=$('#machine-wave'),machineSamples=new Float32Array(256);let machineWaveWidth=0,machineWaveHeight=0;
function sizeMachineWave(){const r=machineCanvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;machineWaveWidth=r.width;machineWaveHeight=r.height;machineCanvas.width=Math.round(r.width*dpr);machineCanvas.height=Math.round(r.height*dpr);}
new ResizeObserver(sizeMachineWave).observe(machineCanvas);
function drawMachineWave(){requestAnimationFrame(drawMachineWave);const c=machineCanvas.getContext('2d'),dpr=window.devicePixelRatio||1,w=machineWaveWidth,h=machineWaveHeight;if(!w||!h)return;c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);if(!machinePowered)return;const active=engine&&ctx?.state==='running';if(active)engine.analyser.getFloatTimeDomainData(machineSamples);c.lineWidth=1.3;c.strokeStyle='#536d3d';c.beginPath();for(let x=0;x<w;x+=2){const value=active?machineSamples[Math.floor(x/w*machineSamples.length)]*h*1.8:Math.sin(x*.18)*.55+Math.sin(x*.067)*.35;const y=Math.max(2,Math.min(h-2,h/2+value));if(x===0)c.moveTo(x,y);else c.lineTo(x,y);}c.stroke();}
requestAnimationFrame(drawMachineWave);
