 const names=state.kit==='toms'?['Kick','Snare','High tom','Low tom']:['Kick','Snare','Hi-hat','Metal'];let html='<span></span>';
 for(let i=0;i<16;i++)html+=`<span class="beat-number ${i%4===0?'quarter':''}">${i%4===0?(Math.floor((bank*16+i)/4)%(state.beatsPerBar||4))+1:'·'}</span>`;
 for(let r=0;r<4;r++){html+=`<button class="drum-name" data-drum-preview="${r}" aria-label="Preview ${names[r]}">${names[r]}</button>`;for(let i=0;i<16;i++){const step=bank*16+i,value=state.patterns.drums[r][step];html+=step>=state.steps?'<span class="beat-cell unused"></span>':`<button class="beat-cell ${i%4===0?'quarter':''} ${value?'on':''} ${playing&&displayed===step?'beat-playing':''}" data-beat-row="${r}" data-beat-step="${step}" aria-label="${names[r]}, page ${bank+1}, step ${i+1}" aria-pressed="${!!value}"></button>`;}}
