 const length=$('#beat-length'),bar=(state.beatsPerBar||4)*4,counts=[1,2,4,8,15,16];length.replaceChildren(...counts.map(n=>new Option(n+' '+(n===1?'bar':'bars'),n*bar)));if(!counts.some(n=>n*bar===state.steps)){const bars=state.steps/bar;length.add(new Option(Number.isInteger(bars)?bars+' bars':state.steps+' steps',state.steps));}length.value=state.steps;$('#follow-playback').setAttribute('aria-pressed',followPlayback);
