let beatGesture=null,lastBeatPointer=-Infinity;
function enableDrums(){const mix=state.mix.drums;if(mix.mute||!mix.volume||TRACKS.some(n=>n!=='drums'&&state.mix[n].solo)){mix.mute=false;if(!mix.volume)mix.volume=65;TRACKS.forEach(n=>state.mix[n].solo=false);updateAudio();renderMixer();}}
function changeBeatCell(cell,value){setFollow(false);if(value)enableDrums();const row=+cell.dataset.beatRow,step=+cell.dataset.beatStep;state.patterns.drums[row][step]=value;state.beatId='';$('#beat-library').value='';$('#beat-description').textContent='Custom rhythm · edit any square, or choose a beat starter.';cell.classList.toggle('on',!!value);cell.setAttribute('aria-pressed',!!value);}
$('#beat-grid').addEventListener('pointerdown',async e=>{const cell=e.target.closest('[data-beat-step]');if(!cell)return;setFollow(false);e.preventDefault();lastBeatPointer=performance.now();const scroller=$('#beat-grid').parentElement;if(e.pointerType==='touch'&&scroller.scrollWidth>scroller.clientWidth+2){beatGesture={pointer:e.pointerId,touchPending:true,scrolling:false,x:e.clientX,y:e.clientY,pageScroll:scrollY,scroll:scroller.scrollLeft,cell};$('#beat-grid').setPointerCapture(e.pointerId);return;}remember();const value=state.patterns.drums[+cell.dataset.beatRow][+cell.dataset.beatStep]?0:e.pointerType==='pen'&&e.pressure>0?Math.max(.15,e.pressure):.75;beatGesture={pointer:e.pointerId,value,last:cell};$('#beat-grid').setPointerCapture(e.pointerId);changeBeatCell(cell,value);try{await ensureAudio();if(!playing&&value)engine.drum(+cell.dataset.beatRow,ctx.currentTime,value);}catch(err){toast(err.message);}});
