for(const type of ['pointerup','pointercancel','lostpointercapture'])$('#beat-grid').addEventListener(type,async e=>{if(!beatGesture)return;const g=beatGesture;beatGesture=null;if(g.touchPending&&!g.scrolling&&e.type==='pointerup'){remember();const cell=g.cell,row=+cell.dataset.beatRow,step=+cell.dataset.beatStep,value=state.patterns.drums[row][step]?0:.75;changeBeatCell(cell,value);autosave();try{await ensureAudio();if(!playing&&value)engine.drum(row,ctx.currentTime,value);}catch(err){toast(err.message);}}else if(!g.touchPending)autosave();});
