// Guided play is a nondestructive view of the current pattern. It never rewrites notes.
function phraseLength(){return ({3:80,4:40,5:64,6:64,7:64,8:64,9:80,10:64,11:96,12:64,13:64,14:96,15:64,16:128,17:64})[state.preset]||state.steps;}
function couchSequence(){const rows=machinePadRows(),passage=passageFor(state,couch.loop),result=[];for(let pos=0;pos<passage.length;pos++){const step=passage.start+pos,pad=rows.findIndex(row=>state.patterns.keys[row]?.[step]>0);if(pad>=0&&(!passage.tracks||passage.tracks.includes('keys')))result.push({pad,step:pos,hold:state.holds?.[rows[pad]]?.[step]||0});}return result;}
function renderCouchLayers(){const holder=$('#sofa-layers');if(!holder)return;for(const n of TRACKS){let card=holder.querySelector('[data-couch-card="'+n+'"]');if(!card){card=document.createElement('div');card.dataset.couchCard=n;card.innerHTML='<button data-couch-layer="'+n+'" aria-label="Toggle '+n+' layer"></button><button data-couch-solo="'+n+'" aria-label="Hear '+n+' alone">Alone</button>';holder.append(card);}const hasNotes=state.patterns[n].some(row=>row.some(v=>v>0)),backing=couch.active&&couch.mode==='play'&&n==='keys';const button=card.firstElementChild;button.textContent=({drums:'Beat',bass:'Bass',keys:'Instrument',sample:'Sample'})[n]+' · '+(backing?'you play':!hasNotes?'empty':trackAudible(n)?'on':'off');button.setAttribute('aria-pressed',trackAudible(n)&&!backing);card.hidden=!hasNotes;button.disabled=backing||!hasNotes;card.lastElementChild.disabled=backing||!hasNotes;card.lastElementChild.setAttribute('aria-pressed',state.mix[n].solo);}}
function renderCouch(){
 if(couch.preset!==state.preset){couchSoloSnapshot=null;couch={active:false,preset:state.preset,mode:'listen',loop:PASSAGES[state.preset]?'phrase':'whole',cursor:0,hints:false};}
 const listeningTips={3:'Hear four softly swelling chords over the restless beat. Choose Main phrase for the twenty-beat chord cycle, or Whole study to hear the drum and chord cycles meet again.',4:'Let the three warm chords turn over in their own ten-beat cycle. Try Instrument alone in Explore layers, then play the numbered pad phrase slowly.',5:'Listen to the piano changes and the moving bass underneath. Hear Bass alone, then bring Instrument back to hear how they fit.',6:'Listen to the bright music-box notes turning from major to minor. Keep your taps gentle and let the bell tails overlap.',7:'Hear the short picked notes against the steady beat. Isolate Instrument to follow its repeating shape, then bring Beat back.',8:'Leave room between the piano chords. Listen for the uneven spacing; the pauses are part of the phrase.',9:'Count one, two, three, four, five. Hear Beat alone first, then add the picked instrument without losing that five-beat pulse.',10:'Hear the spaces between the picked shapes. Take out Beat to hear the harmony clearly, then bring the rhythm back quietly.',11:'Count three gently and listen to the piano tails. This study starts with piano alone; Your turn gives you a click to play against.',12:'Listen to the descending colour of the opening picked chords. Hear Instrument alone, then try the pad phrase over the remaining layers.',13:'Start quietly with the picked chords. Leave space after each change and let the sound decay before you answer.',14:'Count three slowly and let the organ chords overlap. Use Your turn to play the pad phrase with a gentle click.',15:'Start with Bass alone and feel the low syncopated pulse. Add Beat, then bring the soft synth back into the mix.',16:'Hear the repeated piano shape drifting across the percussion. Remove one layer, count four, and bring it back.',17:'Start with Beat alone. Hear the higher and lower toms answer each other, then add the quiet picked chords.'};
 const p=presets[state.preset];$('.sofa-guide').dataset.mode=couch.mode;$$('[data-guide-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.guideMode===couch.mode));
 $('#sofa-title').textContent={listen:'Start with the sound.',layers:'Follow the pulse. Watch the pads.',play:'Play it from memory.'}[couch.mode];
 $('#sofa-instruction').textContent=couch.mode==='listen'?('Press Hear the loop. '+(listeningTips[state.preset]||'Hear the study, then try the four pads below.')) :couch.mode==='layers'?'Press Play. The marker shows where you are in the phrase; a pad lights when its note arrives. Listen once, then play along. Use Alone to hear one layer clearly.':'The instrument part is left for you to play. Start the backing and try the phrase from memory. Show hints whenever you need the timing guide again.';
 if(couch.mode==='play'&&!['drums','bass','sample'].some(n=>trackAudible(n)&&state.patterns[n].some(row=>row.some(Boolean))))$('#sofa-instruction').textContent+=' No backing layers are on: use Click to keep time, or add a rhythm in Edit the beat.';
 const recipe={digital:'Use Tape chord for the softly swelling, glassy voicings. Keep Tone low for a darker attack; add Space for a trailing echo.',prophet:'Use Warm polysynth. Lower Tone for rounded chords; keep Space modest so the changes stay clear.',piano:'Use Grand piano. Tap gently for a softer attack. Lower Tone to mellow the top end and add a little Space.',bell:'Use Glass bell. Leave Tone fairly bright and add a little Space. Play single notes slowly so the tails overlap.',pluck:'Use Picked strings. Keep Space low for definition, then raise it for overlapping echoes. Pencil pressure changes the attack.',organ:'Use Soft organ. Let notes overlap. Lower Tone for a muted glow and add Space to widen the room.',legacy:'Try a pad, then move Tone from dark to bright. Space adds a tempo-linked echo.'};
 $('#sofa-recipe').textContent=(state.preset===4?'Use Song sound for a dark, rounded keyboard with a clear attack. Keep Tone low and Space nearly dry. The upper C stays inside each chord.':recipe[p?.voice||state.voice]||recipe.legacy)+(state.preset===3?' This study layers a six-beat drum model against a twenty-beat chord phrase. The whole fifteen-bar loop lets them realign.':'')+' These are editable teaching sounds; compare with Listen to record.';
 $('#sofa-reset-sound').disabled=!p;
 const passage=passageFor(state,couch.loop),options=PASSAGES[state.preset]||[{id:'phrase',name:'Main phrase'},{id:'whole',name:'Whole study'}];
 $('#sofa-loop').innerHTML=options.map(p=>'<option value="'+p.id+'">'+esc(p.name)+' · '+passageFor(state,p.id).length/4+' beats</option>').join('');
 $('#passage-kind').textContent=passage.kind;$('#refresh-study').hidden=!(PASSAGES[state.preset]&&state.studyRevision!==2);$('#show-hints').hidden=couch.mode!=='play';$('#show-hints').setAttribute('aria-pressed',couch.hints);$('#show-hints').textContent=couch.hints?'Hide hints':'Show hints';
 if(couch.mode==='listen'&&passage.tip)$('#sofa-instruction').textContent=passage.tip;
 $('#sofa-loop').value=couch.loop;$('#sofa-speed').value=[50,75,100].includes(practice.speed)?practice.speed:100;$('#sofa-click').setAttribute('aria-pressed',practice.metronome);
 renderCouchLayers();renderCouchCue();renderCouchTimeline();
}
function renderCouchCue(){const sequence=couchSequence(),cue=$('#sofa-cue'),holder=$('#sofa-sequence');holder.hidden=couch.mode==='listen'||(couch.mode==='play'&&!couch.hints);cue.hidden=holder.hidden;$$('[data-pad]').forEach(b=>b.classList.remove('next-pad'));if(holder.hidden){$$('[data-pad]').forEach(b=>b.classList.remove('due-pad'));return;}
 if(!sequence.length){cue.textContent='Free play: this pattern has no notes on these four pads. Try any pad.';holder.replaceChildren();return;}
 couch.cursor%=sequence.length;const next=sequence[couch.cursor];cue.textContent='Next: pad '+(next.pad+1)+' · '+(state.chordLabels?.[machinePadRows()[next.pad]]||pitchLabel(state.notes[machinePadRows()[next.pad]]))+' · note '+(couch.cursor+1)+' of '+sequence.length+'. Play at your own pace.';
 $$('[data-pad]')[next.pad].classList.add('next-pad');
 const start=Math.floor(couch.cursor/8)*8;holder.innerHTML=sequence.slice(start,start+8).map((note,i)=>'<span class="'+(start+i===couch.cursor?'next':'')+'">'+(note.pad+1)+'<small>beat '+(note.step/4+1)+'</small></span>').join('');
}
function advanceCouch(index){if(!couch.active||couch.mode!=='play'||playing||!couch.hints)return;const sequence=couchSequence();if(sequence[couch.cursor]?.pad===index){couch.cursor=(couch.cursor+1)%sequence.length;renderCouchCue();}else if(sequence.length)$('#sofa-cue').textContent='You played pad '+(index+1)+'. Try highlighted pad '+(sequence[couch.cursor].pad+1)+' next, or keep exploring.';}
function renderCouchTimeline(){const p=passageFor(state,couch.loop),sequence=couchSequence(),visible=couch.mode!=='play'||couch.hints;$('#phrase-timing').hidden=!visible;$('#phrase-timing').style.setProperty('--beat-count',p.length/4);$('#phrase-notes').innerHTML=sequence.map(note=>'<span style="left:'+note.step/p.length*100+'%;width:'+Math.max(.5,Math.min(note.hold||1,p.length-note.step)/p.length*100)+'%" title="Pad '+(note.pad+1)+', beat '+(note.step/4+1)+'">'+(note.pad+1)+'</span>').join('');$('#timing-caption').textContent=p.tracks?.length===1?'Beat study · '+p.length/4+' beats per loop':p.length/4+' beats · '+(visible?'watch the marker and play with the pulse':'play from memory');}
let cueStrike=0;
function cueCouchBeat(event){if(couch.mode==='listen'||(couch.mode==='play'&&!couch.hints))return;const sequence=couchSequence(),p=passageFor(state,couch.loop),pos=event.position%p.length,index=sequence.findIndex(n=>n.step===pos);if(index<0){const last=sequence.findLast(n=>n.step<=pos);if(!last||pos>=last.step+Math.max(1,last.hold))$$('[data-pad]').forEach(b=>b.classList.remove('due-pad'));return;}const note=sequence[index];couch.cursor=index;renderCouchCue();$('#sofa-cue').setAttribute('aria-live','off');$$('[data-pad]').forEach(b=>b.classList.remove('next-pad'));$$('[data-pad]')[note.pad].dataset.strike=String(++cueStrike%2);$$('[data-pad]').forEach((button,i)=>button.classList.toggle('due-pad',i===note.pad));$('#sofa-cue').textContent='Pad '+(note.pad+1)+' now · beat '+(pos/4+1)+(note.hold?' · hold '+note.hold/4+' beats':'');}
function updateCouchClock(){if(!playing||!couch.active||!couchClock||!ctx)return;const p=passageFor(state,couch.loop),fraction=Math.max(0,Math.min(1,(ctx.currentTime-couchClock.time)/stepTime(couchClock.position)));$('#phrase-playhead').style.left=((couchClock.position+fraction)%p.length)/p.length*100+'%';}
$('#show-hints').onclick=()=>{couch.hints=!couch.hints;renderCouch();};
$('#refresh-study').onclick=()=>$('#presets [data-preset="'+state.preset+'"]').click();
function leaveCouch(){couchSoloSnapshot=null;couch.active=false;couch.mode='listen';couch.cursor=0;renderCouch();}
function focusInstrument(){if(innerWidth<761||innerHeight<850){$('.sofa-guide').scrollIntoView({block:'start'});const bottom=$$('[data-pad]').at(-1).getBoundingClientRect().bottom,top=$('.transport-window').getBoundingClientRect().top;if(bottom>top-12)window.scrollBy(0,bottom-top+12);}}
function activateCouch(){const resume=playing||starting;stop();couch.active=true;if(![50,75,100].includes(practice.speed))practice.speed=100;practice.mode='loop';practice.exercise=-1;practice.countIn=false;couch.cursor=0;updateAudio();renderCouch();return resume;}
$$('[data-guide-mode]').forEach(button=>button.onclick=()=>{const resume=activateCouch();couch.mode=button.dataset.guideMode;if(couch.mode==='play'&&!['drums','bass','sample'].some(n=>trackAudible(n)&&state.patterns[n].some(row=>row.some(Boolean))))practice.metronome=true;if(couch.mode==='play'&&TRACKS.some(n=>state.mix[n].solo)){remember();TRACKS.forEach(n=>state.mix[n].solo=false);updateAudio();renderMixer();autosave();}renderMachine();focusInstrument();if(resume)play();});
$('#sofa-reset-sound').onclick=()=>{const p=presets[state.preset];if(!p)return;remember();state.soundPatch='study';state.tone=p.tone;state.space=p.space;updateAudio();renderControls();autosave();toast('Study sound restored. Your notes and layers are unchanged.');};
$('#sofa-library').onclick=()=>$('#change-tape').click();
$('#sofa-loop').onchange=()=>{const value=$('#sofa-loop').value,resume=activateCouch();couch.loop=value;renderMachine();if(resume)play();};
$('#sofa-speed').onchange=()=>{const speed=+$('#sofa-speed').value,resume=activateCouch();practice.speed=speed;updateAudio();renderCouch();renderLesson();if(resume)play();};
$('#sofa-click').onclick=()=>{practice.metronome=!practice.metronome;renderCouch();};
$('#sofa-layers').onclick=e=>{
 const button=e.target.closest('button');if(!button)return;const n=button.dataset.couchLayer||button.dataset.couchSolo;if(!n)return;remember();
 if(couchSoloSnapshot?.source!==state.mix)couchSoloSnapshot=null;
 if(button.dataset.couchSolo){
  const solo=state.mix[n].solo;
  if(couchSoloSnapshot){state.mix=structuredClone(couchSoloSnapshot.mix);couchSoloSnapshot=null;}else TRACKS.forEach(t=>state.mix[t].solo=false);
  if(!solo){couchSoloSnapshot={mix:structuredClone(state.mix),source:state.mix};state.mix[n].solo=true;state.mix[n].mute=false;if(!state.mix[n].volume)state.mix[n].volume=65;}
 }else{
  const audible=trackAudible(n);if(couchSoloSnapshot){state.mix=structuredClone(couchSoloSnapshot.mix);couchSoloSnapshot=null;}TRACKS.forEach(t=>state.mix[t].solo=false);state.mix[n].mute=audible;if(!state.mix[n].volume)state.mix[n].volume=65;
 }
 updateAudio();renderMixer();autosave();
};

function placeTransport(){const rect=$('.desktop-windows').getBoundingClientRect(),bar=$('.transport-window');bar.style.left=rect.left+'px';bar.style.width=rect.width+'px';}
new ResizeObserver(placeTransport).observe($('.desktop-windows'));window.addEventListener('resize',placeTransport);
track=state.preset>=3?'keys':'drums';render();if(savedSessionLoaded)saveStatus(true);
